sp_ListarStatusPedido	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_ListarStatusPedido`()\nBEGIN\n\n    SELECT idStatusPedido, Nome, Descricao\n\n    FROM StatusPedido\n\n    ORDER BY idStatusPedido;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
